"use client";
import * as React from "react";
import { Select as BaseSelect } from "@base-ui-components/react/select";
import { cn } from "@/lib/utils";

// shadcn-style Select on the Base UI primitive. Popup colors are theme tokens only.
export const Select = BaseSelect.Root;

export function SelectTrigger({
  className,
  placeholder,
  ...props
}: React.ComponentProps<typeof BaseSelect.Trigger> & { placeholder?: string }) {
  return (
    <BaseSelect.Trigger
      className={cn(
        "flex h-9 w-full items-center justify-between gap-2 rounded-md border border-border bg-background px-3 text-sm text-foreground",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand",
        "disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      {...props}
    >
      {/* Base UI renders the value via a function; fall back to the placeholder. */}
      <BaseSelect.Value>
        {(value: unknown) =>
          value === null || value === undefined || value === "" ? (
            <span className="text-muted-foreground">{placeholder}</span>
          ) : (
            String(value)
          )
        }
      </BaseSelect.Value>
      <BaseSelect.Icon className="text-muted-foreground">
        <svg viewBox="0 0 12 12" className="h-3 w-3" fill="none" aria-hidden="true">
          <path d="M3 4.5 6 7.5 9 4.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </BaseSelect.Icon>
    </BaseSelect.Trigger>
  );
}

// `container` lets a caller mount the popup inside a themed subtree (the Theme Studio
// previews a theme on a container, and portals default to <body>, outside it).
export function SelectContent({
  className,
  children,
  container,
  ...props
}: React.ComponentProps<typeof BaseSelect.Popup> & {
  container?: React.ComponentProps<typeof BaseSelect.Portal>["container"];
}) {
  return (
    <BaseSelect.Portal container={container}>
      <BaseSelect.Positioner sideOffset={6}>
        <BaseSelect.Popup
          className={cn(
            "min-w-[var(--anchor-width)] rounded-md border border-border bg-background p-1 shadow-lg",
            className
          )}
          {...props}
        >
          {children}
        </BaseSelect.Popup>
      </BaseSelect.Positioner>
    </BaseSelect.Portal>
  );
}

export function SelectItem({ className, children, ...props }: React.ComponentProps<typeof BaseSelect.Item>) {
  return (
    <BaseSelect.Item
      className={cn(
        "flex cursor-default items-center justify-between gap-2 rounded-sm px-2 py-1.5 text-sm text-foreground",
        "data-[highlighted]:bg-muted",
        className
      )}
      {...props}
    >
      <BaseSelect.ItemText>{children}</BaseSelect.ItemText>
      <BaseSelect.ItemIndicator className="text-brand">
        <svg viewBox="0 0 12 12" className="h-3 w-3" fill="none" aria-hidden="true">
          <path d="M2.5 6.5 5 9l4.5-5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </BaseSelect.ItemIndicator>
    </BaseSelect.Item>
  );
}
